{"code": "const zlib = await import("node:zlib");
const fs = await import("node:fs");
const path = await import("node:path");
const MAGIC = Buffer.from([0x28,0xb5,0x2f,0xfd]);
const root = "C:\\Users\\Administrator\\.dsh\\sessions\\--D-lean--";
const files: {p:string; size:number; mtime:number; dir:string}[] = [];
for (const d of fs.readdirSync(root)) {
  const f = path.join(root, d, "session.v4.jsonl.zstd");
  if (fs.existsSync(f)) { const st = fs.statSync(f); files.push({p:f, size:st.size, mtime:st.mtimeMs, dir:d}); }
}
files.sort((a,b)=>b.mtime-a.mtime);
const markers = ["reducedQPilotAnchor", "S1960QPilotAnchor", "S1942PrePsiFive"];
const hits: any[] = [];
const recDir = "D:\\lean\\tmp\\sheaf\\ledger-recovery";
fs.mkdirSync(recDir, { recursive: true });
let scanned = 0, frames = 0; const t0 = Date.now();
for (const f of files) {
  if (Date.now()-f.mtime > 26*3600*1000) break;
  if (Date.now()-t0 > 220000) { console.log("TIME_CAP"); break; }
  if (f.size > 2_500_000) continue;
  const buf = fs.readFileSync(f.p);
  const idx: number[] = [];
  let pos = buf.indexOf(MAGIC, 0);
  while (pos >= 0) { idx.push(pos); pos = buf.indexOf(MAGIC, pos + 1); }
  let fileHas = false;
  for (let k = 0; k < idx.length; k++) {
    const start = idx[k];
    let end = (k+1 < idx.length) ? idx[k+1] : buf.length;
    let out: string | null = null;
    for (let tries = 0; tries < 3; tries++) {
      try { out = (zlib as any).zstdDecompressSync(buf.subarray(start, end)).toString("utf8"); break; }
      catch (e) {
        if (k+1+tries < idx.length) end = idx[k+1+tries];
        else if (tries >= 1) break;
        else end = buf.length;
      }
    }
    if (out === null) continue;
    frames++;
    const found = markers.filter(m => out!.includes(m));
    if (found.length > 0) {
      fileHas = true;
      const outPath = path.join(recDir, "frame-" + f.dir.slice(0,8) + "-" + k + ".json");
      fs.writeFileSync(outPath, out);
      hits.push({dir:f.dir, frame:k, chars:out.length, found, file: outPath});
    }
  }
  if (fileHas) scanned++;
}
console.log("filesScanned:", scanned, "frames:", frames, "elapsed:", Date.now()-t0);
console.log("hits:", JSON.stringify(hits.slice(0,20), null, 1));
console.log("hitCount:", hits.length);
", "description": "Frame-wise scan of sessions for ledger markers", "timeoutMs": 300000}

